// The query executed by GetEventSets.
const GetEventSets_Operation = `
query GetEventSets ($eventId: ID!, $page: Int!) {
	event(id: $eventId) {
		id
		name
		entryFee
		numEntrants
		startAt
		tournament {
			venueName
			venueAddress
		}
		state
		sets(page: $page, perPage: 25) {
			pageInfo {
				page
				totalPages
			}
			nodes {
				id
				fullRoundText
				round
				startedAt
				completedAt
				stream {
					id
					streamName
				}
				slots {
					entrant {
						id
						name
						participants {
							gamerTag
							player {
								id
							}
						}
					}
					standing {
						stats {
							score {
								value
							}
						}
					}
				}
			}
		}
	}
}
`

func GetEventSets(
	ctx_ context.Context,
	client_ graphql.Client,
	eventId ID,
	page int,
) (data_ *GetEventSetsResponse, err_ error) {
	req_ := &graphql.Request{
		OpName: "GetEventSets",
		Query:  GetEventSets_Operation,
		Variables: &__GetEventSetsInput{
			EventId: eventId,
			Page:    page,
		},
	}

	data_ = &GetEventSetsResponse{}
	resp_ := &graphql.Response{Data: data_}

	err_ = client_.MakeRequest(
		ctx_,
		req_,
		resp_,
	)

	return data_, err_
}

